do $$ begin if to_regclass('public.votes') is not null and exists(select 1 from information_schema.columns where table_schema='public' and table_name='votes' and column_name='voter_id') then alter table public.votes rename to legacy_votes; end if; end $$;
create type public.role as enum ('user','admin'); create type public.voting_status as enum ('open','closed');
create table public.users(id uuid primary key default gen_random_uuid(),name varchar(100) not null,email varchar(255) not null unique,password_hash text not null,role public.role not null default 'user',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name varchar(120) not null,slug varchar(140) not null unique,description text not null default '',display_order integer not null default 0,created_at timestamptz not null default now());
create table public.nominees(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.categories(id) on delete cascade,name varchar(160) not null,description text not null default '',image_url text,created_at timestamptz not null default now(),unique(category_id,name));
create table public.voting_state(id boolean primary key default true check(id=true),status public.voting_status not null default 'open',results_published boolean not null default false,updated_at timestamptz not null default now()); insert into public.voting_state(id,status,results_published) values(true,'open',false);
create table public.votes(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id) on delete cascade,category_id uuid not null references public.categories(id) on delete cascade,nominee_id uuid not null references public.nominees(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,category_id));
create index votes_category_nominee_idx on public.votes(category_id,nominee_id); create index nominees_category_idx on public.nominees(category_id);
alter table public.users enable row level security; alter table public.categories enable row level security; alter table public.nominees enable row level security; alter table public.voting_state enable row level security; alter table public.votes enable row level security;
revoke all on public.users,public.categories,public.nominees,public.voting_state,public.votes from anon,authenticated;